// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 attackerDeposit, uint256 victimDeposit) public {
        attackerDeposit = bound(attackerDeposit, 1, 1 ether);
        victimDeposit = bound(victimDeposit, 1, 1 ether);

        Attacker attacker = new Attacker(address(c));

        address victim = address(0xBEEF);
        vm.deal(address(attacker), attackerDeposit);
        vm.deal(victim, victimDeposit);

        vm.prank(victim);
        c.deposit{value: victimDeposit}();

        vm.prank(address(attacker));
        c.deposit{value: attackerDeposit}();

        uint256 before = address(c).balance;

        vm.prank(address(attacker));
        attacker.attackWithdraw();

        uint256 expected = before - attackerDeposit;
        assertTrue(address(c).balance == expected);
    }
}

contract Attacker {
    address target;
    bool reentered;
    constructor(address _target) payable { target = _target; }

    function attackWithdraw() external {
        ReentrancyDAO(target).withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            ReentrancyDAO(target).withdrawAll();
        }
    }
}
